/**
 * Migrate content JSONs to Firestore
 * Collection: "dreams", document ID: slug (e.g. "snake-dream")
 *
 * Usage:
 *   node scripts/migrate-content-to-firestore.mjs
 *   node scripts/migrate-content-to-firestore.mjs --dry-run
 *   node scripts/migrate-content-to-firestore.mjs --slug snake-dream
 */

import { readdir, readFile } from "fs/promises";
import { join, dirname, basename } from "path";
import { fileURLToPath } from "url";
import { existsSync } from "fs";
import admin from "firebase-admin";

const __dirname = dirname(fileURLToPath(import.meta.url));
const PROJECT_ROOT = join(__dirname, "..");
const CONTENT_DIR = join(PROJECT_ROOT, "data/content");
const SERVICE_ACCOUNT_PATH = join(__dirname, "firebase-service-account.json");

const DRY_RUN = process.argv.includes("--dry-run");
const SINGLE_SLUG = process.argv.includes("--slug")
  ? process.argv[process.argv.indexOf("--slug") + 1]
  : null;

// Firestore batch limit is 500 writes per batch
const BATCH_SIZE = 400;

// Initialize Firebase Admin
const serviceAccount = JSON.parse(await readFile(SERVICE_ACCOUNT_PATH, "utf8"));
admin.initializeApp({
  credential: admin.credential.cert(serviceAccount),
});
const db = admin.firestore();
const collection = db.collection("dreams");

let uploaded = 0;
let skipped = 0;
let failed = 0;

async function getAllContentFiles() {
  const results = [];
  const categories = await readdir(CONTENT_DIR, { withFileTypes: true });
  for (const cat of categories.filter((e) => e.isDirectory())) {
    const files = await readdir(join(CONTENT_DIR, cat.name));
    for (const file of files.filter((f) => f.endsWith(".json"))) {
      results.push({
        category: cat.name,
        slug: basename(file, ".json"),
        path: join(CONTENT_DIR, cat.name, file),
      });
    }
  }
  return results.sort((a, b) => a.slug.localeCompare(b.slug));
}

async function migrateInBatches(files) {
  let batch = db.batch();
  let batchCount = 0;
  let batchNum = 1;

  for (const { category, slug, path } of files) {
    let data;
    try {
      const raw = await readFile(path, "utf8");
      data = JSON.parse(raw);
    } catch (err) {
      console.error(`❌ Invalid JSON [${slug}]: ${err.message}`);
      failed++;
      continue;
    }

    // Add category field so we can query by category later
    const doc = { ...data, category, slug };

    if (DRY_RUN) {
      console.log(`  [DRY RUN] Would write: dreams/${slug}`);
      uploaded++;
      continue;
    }

    batch.set(collection.doc(slug), doc);
    batchCount++;
    uploaded++;

    // Commit batch when full
    if (batchCount >= BATCH_SIZE) {
      process.stdout.write(`  Committing batch ${batchNum} (${batchCount} docs)... `);
      await batch.commit();
      console.log("✅");
      batch = db.batch();
      batchCount = 0;
      batchNum++;
    }
  }

  // Commit remaining
  if (batchCount > 0 && !DRY_RUN) {
    process.stdout.write(`  Committing batch ${batchNum} (${batchCount} docs)... `);
    await batch.commit();
    console.log("✅");
  }
}

// Main
console.log(`🚀 Firestore Content Migration`);
console.log(`   Collection: dreams`);
console.log(`   Batch size: ${BATCH_SIZE}`);
if (DRY_RUN) console.log(`   Mode: DRY RUN`);
if (SINGLE_SLUG) console.log(`   Slug: ${SINGLE_SLUG} only`);
console.log("");

let files = await getAllContentFiles();

if (SINGLE_SLUG) {
  files = files.filter((f) => f.slug === SINGLE_SLUG);
  if (files.length === 0) {
    console.error(`No content file found for slug: ${SINGLE_SLUG}`);
    process.exit(1);
  }
}

console.log(`📁 Found ${files.length} content files\n`);

// List all files being migrated
for (const { category, slug } of files) {
  console.log(`  ${category}/${slug}`);
}
console.log("");

await migrateInBatches(files);

console.log(`
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
✅ Done
   Uploaded: ${uploaded}
   Failed:   ${failed}
${DRY_RUN ? "\n⚠️  DRY RUN — nothing was written to Firestore" : ""}
`);

process.exit(0);

/**
 * Firebase Admin SDK singleton for server-side Firestore access.
 * Credentials come from environment variables set in Vercel (or .env.local for dev).
 */

import "server-only";
import admin from "firebase-admin";

function getApp(): admin.app.App {
  if (admin.apps.length > 0) return admin.apps[0]!;

  return admin.initializeApp({
    credential: admin.credential.cert({
      projectId: process.env.FIREBASE_PROJECT_ID,
      clientEmail: process.env.FIREBASE_CLIENT_EMAIL,
      // Vercel stores multiline env vars with literal \n — replace them
      privateKey: process.env.FIREBASE_PRIVATE_KEY?.replace(/\\n/g, "\n"),
    }),
  });
}

export function getFirestore(): admin.firestore.Firestore {
  return getApp().firestore();
}

/**
 * Content data access utilities.
 * Reads from Firestore collection "dreams", document ID = english slug.
 */

import "server-only";
import type { Locale } from "@/i18n/routing";
import { getSymbolBySlug } from "./taxonomy";
import { getFirestore } from "./firestore";

export type ContentSection = {
  type: string;
  heading: string;
  body: string;
  imageRef?: string;
};

export type ContentVariation = {
  keyword: string;
  heading: string;
  body: string;
};

export type ContentFAQ = {
  question: string;
  answer: string;
};

export type LocaleContent = {
  title: string;
  metaDescription: string;
  h1: string;
  intro: string;
  sections: ContentSection[];
  variations: ContentVariation[];
  culturalContext: string;
  /** Bilingual western psychology section (Freud/Jung/modern/cross-cultural). Markdown string. */
  westernContext?: string;
  faqs: ContentFAQ[];
  conclusion: string;
};

export type DreamContent = {
  ko: LocaleContent;
  en: LocaleContent;
  images: {
    hero?: string;
    sections?: Record<string, string>;
  };
  seo: {
    slug: string;
    koreanSlug: string;
    ogTitle: { ko: string; en: string };
    ogDescription: { ko: string; en: string };
    ogImage?: string;
    structuredData: {
      faqSchema: object | null;
      articleSchema: object | null;
    };
    hreflang: { ko: string; en: string };
    relatedSlugs?: string[];
    naverSEO: { blogPostTitle: string; tags: string[] };
  };
};

export type ContentPreview = {
  slug: string;
  koreanSlug: string;
  title: { ko: string; en: string };
  excerpt: { ko: string; en: string };
  heroImage?: string;
  badgeType: "auspicious" | "inauspicious" | "neutral";
};

function detectBadge(heading: string): ContentPreview["badgeType"] {
  if (heading.includes("길몽") || /auspicious/i.test(heading)) return "auspicious";
  if (heading.includes("흉몽") || /inauspicious/i.test(heading)) return "inauspicious";
  return "neutral";
}

export async function getAvailableContentSlugs(): Promise<string[]> {
  try {
    const db = getFirestore();
    const refs = await db.collection("dreams").listDocuments();
    return refs.map((r) => r.id);
  } catch {
    return [];
  }
}

export async function getContentPreviews(slugs?: string[]): Promise<ContentPreview[]> {
  try {
    const db = getFirestore();
    const targetSlugs = slugs ?? (await getAvailableContentSlugs());

    // Fetch in batches of 10 (Firestore `in` query limit)
    const previews: ContentPreview[] = [];
    for (let i = 0; i < targetSlugs.length; i += 10) {
      const batch = targetSlugs.slice(i, i + 10);
      const snap = await db
        .collection("dreams")
        .where(admin.firestore.FieldPath.documentId(), "in", batch)
        .get();

      for (const doc of snap.docs) {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const data = doc.data() as any;
        const firstHeading = data?.ko?.sections?.[0]?.heading ?? "";
        previews.push({
          slug: doc.id,
          koreanSlug: data?.seo?.koreanSlug ?? "",
          title: { ko: data?.ko?.title ?? "", en: data?.en?.title ?? "" },
          excerpt: {
            ko: (data?.ko?.intro ?? "").slice(0, 130).trim() + "…",
            en: (data?.en?.intro ?? "").slice(0, 130).trim() + "…",
          },
          heroImage: data?.images?.hero,
          badgeType: detectBadge(firstHeading),
        });
      }
    }
    return previews;
  } catch {
    return [];
  }
}

export async function getContent(
  slug: string,
  locale: Locale
): Promise<DreamContent | null> {
  const resolvedSlug = await resolveToEnglishSlug(slug, locale);
  if (!resolvedSlug) return null;

  // Sanitize slug
  const safe = resolvedSlug.replace(/[^a-zA-Z0-9_-]/g, "");

  try {
    const db = getFirestore();
    const doc = await db.collection("dreams").doc(safe).get();
    if (!doc.exists) return null;
