const types = ['hero', 'auspicious', 'inauspicious'];

async function upload() {
  for (const type of types) {
    const localPath = \`public/images/dreams/\${slug}/\${type}.webp\`;
    const remotePath = \`images/dreams/\${slug}/\${type}.webp\`;
    await bucket.upload(localPath, {
      destination: remotePath,
      metadata: { contentType: 'image/webp', cacheControl: 'public, max-age=31536000' }
    });
    await bucket.file(remotePath).makePublic();
    console.log('Uploaded:', remotePath);
  }
  console.log('All done!');
  process.exit(0);
}
upload().catch(e => { console.error(e); process.exit(1); });
" 2>&1

